# area: narrowing_builtin
# hypothesis: An alias is_none = a.x is None computed once before a while loop goes stale after a.x is reset to None at the end of the body, so the aliased branch reads None at runtime and checkers should report the None operand, while recomputing the alias inside the loop stays sound.
from typing import reveal_type


class Box:
    def __init__(self, x: int | None) -> None:
        self.x = x


def drain_stale(a: Box) -> int:
    is_none = a.x is None
    total = 0
    count = 0
    while count < 2:
        if not is_none:
            total += a.x + 1  # expect-error
        a.x = None
        count += 1
    return total


def drain_recomputed(a: Box) -> int:
    total = 0
    count = 0
    while count < 2:
        is_none = a.x is None
        if not is_none:
            total += a.x + 1
        a.x = None
        count += 1
    return total


try:
    print(drain_stale(Box(3)))
except TypeError as exc:
    print('stale alias TypeError:', exc)
print(drain_recomputed(Box(3)))
reveal_type(drain_recomputed(Box(None)))
